    parts = [(t.text or "") for t in t_elems]
    return ParagraphText(t_elems=t_elems, full_text="".join(parts))


def replace_placeholders_in_text(text: str, values: Dict[str, str]) -> Tuple[str, bool]:
    changed = False

    def repl(m: re.Match) -> str:
        nonlocal changed
        key = m.group(1).strip()
        if key in values:
            changed = True
            if key == "예산":
                return format_budget(values[key])
            return values[key]
        return m.group(0)

    new_text = PLACEHOLDER_RE.sub(repl, text)
    if new_text != text:
        changed = True
    return new_text, changed


def set_paragraph_text_single_t(ptext: ParagraphText, new_text: str) -> None:
    """Set paragraph text by putting all content into the first <hp:t> and clearing the rest.

    This handles placeholders spanning multiple <hp:t> by collapsing to a single text node.
    """
    if not ptext.t_elems:
        return
    ptext.t_elems[0].text = new_text
    for t in ptext.t_elems[1:]:
        t.text = ""


