    tree = ET.parse(path)
    root = tree.getroot()

    file_modified = False
    modified_paras = 0

    for p in iter_hp_p_elements(root):
        ptext = get_paragraph_text(p)
        original = ptext.full_text

        replaced, ph_changed = replace_placeholders_in_text(original, values)
        replaced2 = append_phase_months(replaced)

