    mimetype = tmpdir / "mimetype"
    if not mimetype.exists():
        # Minimal HWPX packages often include this; create if missing.
        mimetype.write_text("application/hancom.hwpx", encoding="utf-8")


def build_zip(src_dir: Path, out_path: Path) -> None:
    ensure_mimetype(src_dir)

    # Deterministic ordering: mimetype first, then everything else sorted.
    all_files = [p for p in src_dir.rglob("*") if p.is_file()]
    rels = [p.relative_to(src_dir) for p in all_files]

    # Make sure mimetype exists and is first.
    mimetype_rel = Path("mimetype")
    others = sorted([r for r in rels if r != mimetype_rel], key=lambda p: str(p).replace("\\", "/"))

    with zipfile.ZipFile(out_path, "w") as z:
        # mimetype first: stored.
        z.write(src_dir / mimetype_rel, arcname=str(mimetype_rel).replace("\\", "/"), compress_type=zipfile.ZIP_STORED)
        for r in others:
            z.write(src_dir / r, arcname=str(r).replace("\\", "/"), compress_type=zipfile.ZIP_DEFLATED)


def main() -> None:
    template = Path("/root/project_proposal_template.hwpx")
    json_path = Path("/root/project_proposal.json")
    out_path = Path("/root/project_proposal_ready.hwpx")

    values = load_json(json_path)

    with tempfile.TemporaryDirectory(prefix="hwpx_fill_") as td:
        td_path = Path(td)
        with zipfile.ZipFile(template, "r") as z:
            z.extractall(td_path)

        # Process ALL XML files.
        xml_files = sorted([p for p in td_path.rglob("*.xml") if p.is_file()])
        for xf in xml_files:
            process_xml_file(xf, values)

        build_zip(td_path, out_path)


if __name__ == "__main__":
    main()

