    parts = [(t.text or "") for t in t_elems]
    return ParagraphText(t_elems=t_elems, full_text="".join(parts))


def replace_placeholders_in_text(text: str, values: Dict[str, str]) -> Tuple[str, bool]:
    changed = False

    def repl(m: re.Match) -> str:
        nonlocal changed
        key = m.group(1).strip()
        if key in values:
            changed = True
            if key == "예산":
                return format_budget(values[key])
            return values[key]
        return m.group(0)

    new_text = PLACEHOLDER_RE.sub(repl, text)
    if new_text != text:
        changed = True
    return new_text, changed


def set_paragraph_text_single_t(ptext: ParagraphText, new_text: str) -> None:
    """Set paragraph text by putting all content into the first <hp:t> and clearing the rest.

    This handles placeholders spanning multiple <hp:t> by collapsing to a single text node.
    """
    if not ptext.t_elems:
        return
    ptext.t_elems[0].text = new_text
    for t in ptext.t_elems[1:]:
        t.text = ""


def process_xml_file(path: Path, values: Dict[str, str]) -> Tuple[bool, int]:
    """Process one XML file.

    Returns: (file_modified, count_modified_paragraphs)
    """
    tree = ET.parse(path)
    root = tree.getroot()

    file_modified = False
    modified_paras = 0

    for p in iter_hp_p_elements(root):
        ptext = get_paragraph_text(p)
        original = ptext.full_text

        replaced, ph_changed = replace_placeholders_in_text(original, values)
        replaced2 = append_phase_months(replaced)

        if replaced2 != original:
            set_paragraph_text_single_t(ptext, replaced2)
            file_modified = True
            modified_paras += 1

            # Remove layout cache elements in modified paragraphs.
            remove_linesegarray_children(p)

    if file_modified:
        # Preserve original formatting as much as possible: ElementTree will rewrite;
        # these XML files are single-line anyway.
        tree.write(path, encoding="utf-8", xml_declaration=True)

    return file_modified, modified_paras


def ensure_mimetype(tmpdir: Path) -> None:
    mimetype = tmpdir / "mimetype"
    if not mimetype.exists():
        # Minimal HWPX packages often include this; create if missing.
        mimetype.write_text("application/hancom.hwpx", encoding="utf-8")


def build_zip(src_dir: Path, out_path: Path) -> None:
    ensure_mimetype(src_dir)

    # Deterministic ordering: mimetype first, then everything else sorted.
    all_files = [p for p in src_dir.rglob("*") if p.is_file()]
    rels = [p.relative_to(src_dir) for p in all_files]

    # Make sure mimetype exists and is first.
    mimetype_rel = Path("mimetype")
    others = sorted([r for r in rels if r != mimetype_rel], key=lambda p: str(p).replace("\\", "/"))

    with zipfile.ZipFile(out_path, "w") as z:
        # mimetype first: stored.
        z.write(src_dir / mimetype_rel, arcname=str(mimetype_rel).replace("\\", "/"), compress_type=zipfile.ZIP_STORED)
        for r in others:
            z.write(src_dir / r, arcname=str(r).replace("\\", "/"), compress_type=zipfile.ZIP_DEFLATED)


def main() -> None:
    template = Path("/root/project_proposal_template.hwpx")
    json_path = Path("/root/project_proposal.json")
    out_path = Path("/root/project_proposal_ready.hwpx")

    values = load_json(json_path)

    with tempfile.TemporaryDirectory(prefix="hwpx_fill_") as td:
        td_path = Path(td)
        with zipfile.ZipFile(template, "r") as z:
            z.extractall(td_path)

        # Process ALL XML files.
        xml_files = sorted([p for p in td_path.rglob("*.xml") if p.is_file()])
        for xf in xml_files:
            process_xml_file(xf, values)

        build_zip(td_path, out_path)


if __name__ == "__main__":
    main()

